(12490, 'adq_quotelist_page_id', '2032', 'yes'),
(12491, 'woocommerce_adq_admin_new_quote_settings', 'a:12:{s:7:\"enabled\";s:3:\"yes\";s:2:\"id\";s:19:\"adq_admin_new_quote\";s:5:\"title\";s:20:\"New requests (admin)\";s:11:\"description\";s:77:\"This type of email is sent to the admin when a new quote request is received.\";s:7:\"heading\";s:28:\"You have a new quote request\";s:7:\"subject\";s:53:\"{site_title} received a quote request on {order_date}\";s:7:\"content\";s:267:\"<p>You have received a quote request from {adq_customer}. The request is as follows:</p><p></p><p>Request: {order_number} ({order_date})</p><p> {adq_cf7} </p><p> {adq_request_list} </p><p></p> <p>{adq_address}</p><p>Customer comments:</p><p> {adq_order_comments} </p>\";s:10:\"email_type\";s:4:\"html\";s:7:\"send_to\";s:5:\"admin\";s:12:\"order_status\";s:7:\"request\";s:11:\"is_reminder\";s:2:\"no\";s:10:\"is_request\";s:2:\"no\";}', 'yes'),
(12492, 'woocommerce_adq_admin_note_settings', 'a:12:{s:7:\"enabled\";s:3:\"yes\";s:2:\"id\";s:14:\"adq_admin_note\";s:5:\"title\";s:21:\"Customer note (admin)\";s:11:\"description\";s:66:\"This type of email is sent when a customer add a note to an order.\";s:7:\"heading\";s:27:\"A customer has added a note\";s:7:\"subject\";s:74:\"A customer has added a note to the order from {site_title} on {order_date}\";s:7:\"content\";s:168:\"<p>Hello, a customer has added a new note:</p><p>{adq_order_note}</p><p></p><p>Request: {order_number} ({order_date})</p><p> {adq_request_list}</p><p> {adq_address}</p>\";s:10:\"email_type\";s:4:\"html\";s:7:\"send_to\";s:5:\"admin\";s:12:\"order_status\";s:10:\"added-note\";s:11:\"is_reminder\";s:2:\"no\";s:10:\"is_request\";s:2:\"no\";}', 'yes'),
(12493, 'woocommerce_adq_admin_proposal_ko_settings', 'a:12:{s:7:\"enabled\";s:3:\"yes\";s:2:\"id\";s:21:\"adq_admin_proposal_ko\";s:5:\"title\";s:23:\"Admin proposal declined\";s:11:\"description\";s:54:\"Send email confirming the declination of the proposal.\";s:7:\"heading\";s:17:\"Proposal Declined\";s:7:\"subject\";s:36:\"A customer has rejected our proposal\";s:7:\"content\";s:192:\"<p>The proposal from {adq_customer} has been rejected. The request was as follows:</p><p></p><p>Request: {order_number} ({order_date})</p><p> {adq_request_list}</p><p></p><p> {adq_address}</p>\";s:10:\"email_type\";s:4:\"html\";s:7:\"send_to\";s:5:\"admin\";s:12:\"order_status\";s:17:\"proposal-rejected\";s:11:\"is_reminder\";s:2:\"no\";s:10:\"is_request\";s:2:\"no\";}', 'yes'),
(12494, 'woocommerce_adq_admin_proposal_ok_settings', 'a:12:{s:7:\"enabled\";s:3:\"yes\";s:2:\"id\";s:21:\"adq_admin_proposal_ok\";s:5:\"title\";s:23:\"Admin proposal accepted\";s:11:\"description\";s:61:\"Send an email confirming that the proposal has been accepted.\";s:7:\"heading\";s:17:\"Proposal accepted\";s:7:\"subject\";s:37:\"A customer has accepted your proposal\";s:7:\"content\";s:193:\"<p>The proposal from {adq_customer} has been accepted. The request was as follows:</p><p></p><p>Request: {order_number} ({order_date})</p><p> {adq_request_list} </p><p></p><p> {adq_address}</p>\";s:10:\"email_type\";s:4:\"html\";s:7:\"send_to\";s:5:\"admin\";s:12:\"order_status\";s:17:\"proposal-accepted\";s:11:\"is_reminder\";s:2:\"no\";s:10:\"is_request\";s:2:\"no\";}', 'yes'),
(12495, 'woocommerce_adq_customer_note_settings', 'a:12:{s:7:\"enabled\";s:3:\"yes\";s:2:\"id\";s:17:\"adq_customer_note\";s:5:\"title\";s:13:\"Customer note\";s:11:\"description\";s:62:\"Customer note emails are sent when you add a note to an order.\";s:7:\"heading\";s:27:\"A customer has added a note\";s:7:\"subject\";s:53:\"Note added to your {site_title} order on {order_date}\";s:7:\"content\";s:397:\"<p>Hello {adq_customer}, a note has just been added to your order:</p><p> {adq_order_note} </p><p></p><p> You can access your account area to view your orders here: {adq_myaccount_link}. </p><p></p><p> For your reference, your order details are shown below. </p><p></p><p> Order #{order_number} </p><p> {adq_request_list} </p><p></p><p> {adq_address} </p><p></p><p> Thanks,</p><p>Best regards!</p>\";s:10:\"email_type\";s:4:\"html\";s:7:\"send_to\";s:8:\"customer\";s:12:\"order_status\";s:10:\"added-note\";s:11:\"is_reminder\";s:2:\"no\";s:10:\"is_request\";s:2:\"no\";}', 'yes'),
(12496, 'woocommerce_customer_proposal_ko_settings', 'a:12:{s:7:\"enabled\";s:3:\"yes\";s:2:\"id\";s:20:\"customer_proposal_ko\";s:5:\"title\";s:26:\"Customer proposal rejected\";s:11:\"description\";s:54:\"Send email confirming the declination of the proposal.\";s:7:\"heading\";s:17:\"Proposal Declined\";s:7:\"subject\";s:59:\"You have declined our {site_title} proposal on {order_date}\";s:7:\"content\";s:353:\"<p>Hello {adq_customer}!</p><p> Our proposal has been rejected. The proposal is shown below for your reference:</p><p></p><p> You can access your account area to view your orders here: {adq_myaccount_link}.</p><p></p><p> The proposal: {order_number} </p><p> {adq_request_list} </p><p></p><p> {adq_address} </p><p></p><p> Thanks,</p><p> Best regards!</p>\";s:10:\"email_type\";s:4:\"html\";s:7:\"send_to\";s:8:\"customer\";s:12:\"order_status\";s:17:\"proposal-rejected\";s:11:\"is_reminder\";s:2:\"no\";s:10:\"is_request\";s:2:\"no\";}', 'yes'),
(12497, 'woocommerce_adq_customer_proposal_ok_settings', 'a:12:{s:7:\"enabled\";s:3:\"yes\";s:2:\"id\";s:24:\"adq_customer_proposal_ok\";s:5:\"title\";s:26:\"Customer proposal accepted\";s:11:\"description\";s:61:\"Send an email confirming that the proposal has been accepted.\";s:7:\"heading\";s:17:\"Proposal accepted\";s:7:\"subject\";s:61:\"You have accepted our {site_title} proposal from {order_date}\";s:7:\"content\";s:422:\"<p>Hello {adq_customer}!</p><p> Our proposal has been accepted. The proposal is shown below for your reference:</p><p></p><p.> You can proceed with the payment: {adq_pay}.</p><p></p><p.> You can access your account area to view and pay your orders here: {adq_myaccount_link}.</p><p></p><p.> The proposal: {order_number}</p><p> {adq_request_list}</p><p></p><p.> {adq_address}</p><p></p><p.> Thanks,</p><p> Best regards!</p>\";s:10:\"email_type\";s:4:\"html\";s:7:\"send_to\";s:8:\"customer\";s:12:\"order_status\";s:17:\"proposal-accepted\";s:11:\"is_reminder\";s:2:\"no\";s:10:\"is_request\";s:2:\"no\";}', 'yes'),
(12498, 'woocommerce_adq_customer_proposal_settings', 'a:12:{s:7:\"enabled\";s:3:\"yes\";s:2:\"id\";s:21:\"adq_customer_proposal\";s:5:\"title\";s:13:\"Send proposal\";s:11:\"description\";s:111:\"Send proposal emails are sent to the customer when a proposal is ready for the customer to accept or reject it.\";s:7:\"heading\";s:12:\"Our proposal\";s:7:\"subject\";s:44:\"{site_title} sent a proposal on {order_date}\";s:7:\"content\";s:483:\"<p>Hello {adq_customer}!</p><p> Your Quote Request has been processed. Find below our proposal for your reference.</p><p></p><p> You can access your account area to view your proposal here: {adq_myaccount_link}. </p><p></p><p> You can {adq_accept} or {adq_reject} our proposal.</p><p></p><p> {adq_cf7} </p><p></p><p> Your request details are shown below for your reference: </p><p></p><p> {adq_request_list}</p><p></p><p> {adq_address} </p><p></p><p> Thanks,</p><p> Best regards!</p>\";s:10:\"email_type\";s:4:\"html\";s:7:\"send_to\";s:8:\"customer\";s:12:\"order_status\";s:13:\"proposal-sent\";s:11:\"is_reminder\";s:2:\"no\";s:10:\"is_request\";s:2:\"no\";}', 'yes'),
(12499, 'woocommerce_adq_customer_quote_settings', 'a:12:{s:7:\"enabled\";s:3:\"yes\";s:2:\"id\";s:18:\"adq_customer_quote\";s:5:\"title\";s:16:\"Customer request\";s:11:\"description\";s:84:\"Customer request emails are sent to the customer after a request has been submitted.\";s:7:\"heading\";s:30:\"Your request has been received\";s:7:\"subject\";s:61:\"Your {site_title} Quote Request from {order_date} is received\";s:7:\"content\";s:455:\"<p>Hello {adq_customer}!</p><p> Your Quote Request has been received and is now being processed.</p><p></p><p> You can access your account area to view your orders here: {adq_myaccount_link}. </p><p></p><p> {adq_cf7}</p><p></p><p> Your request details are shown below for your reference:</p><p></p><p> {adq_request_list} </p><p></p><p> {adq_address} </p><p></p><p> Your comments:</p><p> {adq_order_comments} </p><p></p><p> Thanks,</p><p> Best regards!</p>\";s:10:\"email_type\";s:4:\"html\";s:7:\"send_to\";s:8:\"customer\";s:12:\"order_status\";s:7:\"request\";s:11:\"is_reminder\";s:2:\"no\";s:10:\"is_request\";s:3:\"yes\";}', 'yes'),
(12500, 'woocommerce_adq_proposal_reminder_settings', 'a:12:{s:7:\"enabled\";s:3:\"yes\";s:2:\"id\";s:21:\"adq_proposal_reminder\";s:5:\"title\";s:15:\"Remind proposal\";s:11:\"description\";s:122:\"Remind proposal emails are sent to the customer when the proposal goes to expire and it has not been accepted or rejected.\";s:7:\"heading\";s:34:\"Our proposal has not been answered\";s:7:\"subject\";s:56:\"Our {site_title} quotation from {order_date} is proposed\";s:7:\"content\";s:356:\"<p>Hello {adq_customer}! </p><p> This is a reminder of our proposal which is shown below for your reference:</p><p></p><p> You can access your account area to view your orders here: {adq_myaccount_link}.</p><p></p><p> Our proposal: {order_number}</p><p></p><p> {adq_request_list} </p><p></p><p> {adq_address} </p><p></p><p> Thanks,</p><p> Best regards!</p>\";s:10:\"email_type\";s:4:\"html\";s:7:\"send_to\";s:8:\"customer\";s:12:\"order_status\";s:13:\"proposal-sent\";s:11:\"is_reminder\";s:3:\"yes\";s:10:\"is_request\";s:2:\"no\";}', 'yes'),
(12501, 'adq_emails', 'a:10:{i:0;s:19:\"adq_admin_new_quote\";i:1;s:14:\"adq_admin_note\";i:2;s:21:\"adq_admin_proposal_ko\";i:3;s:21:\"adq_admin_proposal_ok\";i:4;s:17:\"adq_customer_note\";i:5;s:20:\"customer_proposal_ko\";i:6;s:24:\"adq_customer_proposal_ok\";i:7;s:21:\"adq_customer_proposal\";i:8;s:18:\"adq_customer_quote\";i:9;s:21:\"adq_proposal_reminder\";}', 'yes'),
