selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"43e0997\"},{\"text\":\"This video explains some of the sliding glass roof features\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"1e98587\"}]},\"elements\":[],\"widgetType\":\"icon-list\"},{\"id\":\"dd47b4e\",\"elType\":\"widget\",\"settings\":{\"title\":\"INSTALLATION TIME COMPARISON\",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"px\",\"size\":16,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"3a13d8f\",\"elType\":\"widget\",\"settings\":{\"icon_list\":[{\"text\":\"Complete roof with conventional roof windows\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"_id\":\"02f3139\",\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"}},{\"text\":\"Complete roof without any windows\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"cf8b109\"},{\"text\":\"Sliding glass roof\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"6bf753a\"},{\"text\":\"A normal roof needs a lot of materials and work; wood, roofing felt, insulation material, inner ceiling, windows, sanding, painting, etc.\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"43e0997\"},{\"text\":\"Our sliding glass roofs are premade custom, according to your measurements.\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\"