(12558, 1943, '_elementor_data', '[{\"id\":\"a98013f\",\"elType\":\"section\",\"settings\":{\"rey_modal_id\":\"#modal-5efce73acc0e1\",\"rey_tabs_id\":\"tabs-5efce73acc103\"},\"elements\":[{\"id\":\"101f2f8\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null},\"elements\":[{\"id\":\"3f3d150\",\"elType\":\"widget\",\"settings\":{\"editor\":\"The insulated retractable sliding glass roof systems we provide are well known for their reliability. The roof system can be found in commercial buildings, restaurants, caf\\u00e9s, sport halls, hockey arenas, palaces, private houses, public buildings etc. The customer who is looking for a sliding glass roof is usually have a project visualized, and don\\u2019t want to be limited by conventional skylights or roof windows.\",\"align\":\"justify\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"924faa5\",\"elType\":\"widget\",\"settings\":{\"editor\":\"The insulated sliding roof is very versatile and can have multiple functions, such as : \",\"align\":\"justify\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"7561fa3\",\"elType\":\"widget\",\"settings\":{\"icon_list\":[{\"text\":\"Covering an enclosed area, 75% retractable\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"_id\":\"02f3139\",\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"}},{\"text\":\"Resting on top of structure, 100% retractable\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"cf8b109\"},{\"text\":\"A gazebo, used as the full roof structure of the gazebo\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"6bf753a\"},{\"text\":\"Terrace entrance, can be used as a hatch in the roof to enter the roof area\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"43e0997\"},{\"text\":\"This video explains some of the sliding glass roof features\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"1e98587\"}]},\"elements\":[],\"widgetType\":\"icon-list\"},{\"id\":\"dd47b4e\",\"elType\":\"widget\",\"settings\":{\"title\":\"INSTALLATION TIME COMPARISON\",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"px\",\"size\":16,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"3a13d8f\",\"elType\":\"widget\",\"settings\":{\"icon_list\":[{\"text\":\"Complete roof with conventional roof windows\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"_id\":\"02f3139\",\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"}},{\"text\":\"Complete roof without any windows\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"cf8b109\"},{\"text\":\"Sliding glass roof\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"6bf753a\"},{\"text\":\"A normal roof needs a lot of materials and work; wood, roofing felt, insulation material, inner ceiling, windows, sanding, painting, etc.\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"43e0997\"},{\"text\":\"Our sliding glass roofs are premade custom, according to your measurements.\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"1e98587\"},{\"text\":\"Installation time on site is minimized and saves you money!\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"0947e7f\"}]},\"elements\":[],\"widgetType\":\"icon-list\"}],\"isInner\":false}],\"isInner\":false},{\"id\":\"f00db90\",\"elType\":\"section\",\"settings\":{\"rey_modal_id\":\"#modal-5efce73acc0e1\",\"rey_tabs_id\":\"tabs-5efce73acc103\",\"structure\":\"30\",\"padding\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"0\",\"bottom\":\"20\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"3bbd3ad\",\"elType\":\"column\",\"settings\":{\"_column_size\":33,\"_inline_size\":null},\"elements\":[{\"id\":\"e19ca94\",\"elType\":\"widget\",\"settings\":{\"title\":\"Material Use\",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"px\",\"size\":16,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"aa93581\",\"elType\":\"widget\",\"settings\":{\"icon_list\":[{\"text\":\"Aluminium Extrusion \",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"_id\":\"02f3139\",\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"}},{\"text\":\"S.S. Framework\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"cf8b109\"},{\"text\":\"Indian Made heavy duty cycle motors \",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"b36ed37\"},{\"text\":\"Or\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id