ements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"0287089\",\"elType\":\"widget\",\"settings\":{\"editor\":\"We have been growing and improving our products for You, our customers.\\nWe are a leading products and manufacturing company, we understand the change in current needs and strive hard to make that change reach You, our customers without compromising on Quality.\\nWe offer high-quality products that reflect our goal to bring our customers leading technologies in Interior Engineering. \",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"px\",\"size\":16,\"sizes\":[]},\"align_mobile\":\"center\",\"typography_font_size_tablet\":{\"unit\":\"px\",\"size\":16,\"sizes\":[]},\"align\":\"justify\",\"text_color\":\"#000000\"},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true},{\"id\":\"95730d8\",\"elType\":\"column\",\"settings\":{\"_column_size\":50,\"_inline_size\":null},\"elements\":[{\"id\":\"85bbd05\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/www.iknowledgesolution.com\\/work\\/kiranslidocraft\\/wp-content\\/uploads\\/2020\\/05\\/P_20160408_131344_1_HDR_p.jpg\",\"id\":1260},\"image_size\":\"full\"},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":true}],\"isInner\":true}],\"isInner\":false}],\"isInner\":false},{\"id\":\"6aabfe5\",\"elType\":\"section\",\"settings\":{\"margin\":{\"unit\":\"px\",\"top\":\"50\",\"right\":0,\"bottom\":\"50\",\"left\":0,\"isLinked\":false},\"margin_mobile\":{\"unit\":\"px\",\"top\":\"40\",\"right\":0,\"bottom\":\"40\",\"left\":0,\"isLinked\":false},\"rey_modal_id\":\"#modal-5cc9bb44efcea\",\"rey_tabs_id\":\"tabs-5cf8cdc2a2406\"},\"elements\":[{\"id\":\"6dca2c4\",\"elType\":\"column\",\"settings\":{\"_column_size\":100},\"elements\":[{\"id\":\"d96867b\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/www.iknowledgesolution.com\\/work\\/kiranslidocraft\\/wp-content\\/uploads\\/2020\\/05\\/slidingroof.jpg\",\"id\":1264},\"image_size\":\"full\"}