:{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"1e98587\"},{\"text\":\"Installation time on site is minimized and saves you money!\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"0947e7f\"}]},\"elements\":[],\"widgetType\":\"icon-list\"}],\"isInner\":false}],\"isInner\":false},{\"id\":\"f00db90\",\"elType\":\"section\",\"settings\":{\"rey_modal_id\":\"#modal-5efce73acc0e1\",\"rey_tabs_id\":\"tabs-5efce73acc103\",\"structure\":\"30\",\"padding\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"0\",\"bottom\":\"20\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"3bbd3ad\",\"elType\":\"column\",\"settings\":{\"_column_size\":33,\"_inline_size\":null},\"elements\":[{\"id\":\"e19ca94\",\"elType\":\"widget\",\"settings\":{\"title\":\"Material Use\",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"px\",\"size\":16,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"aa93581\",\"elType\":\"widget\",\"settings\":{\"icon_list\":[{\"text\":\"Aluminium Extrusion \",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"_id\":\"02f3139\",\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"}},{\"text\":\"S.S. Framework\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"cf8b109\"},{\"text\":\"Indian Made heavy duty cycle motors \",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id\":\"b36ed37\"},{\"text\":\"Or\",\"selected_icon\":{\"value\":\"fas fa-check\",\"library\":\"fa-solid\"},\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"_id